/**
 * A claim's fields as the form submits them; a missing date takes the sheet's today. A negative amount is a
 * correction, and corrects names the number of the settled claim it corrects.
 */
public record ClaimForm(@NotNull @Digits(integer = 12, fraction = 2) BigDecimal amount, LocalDate date,
        @Size(max = 500) String note, @Size(max = 140) String corrects) {
}

/** The claims a bulk action is to change, by id. */
public record BulkForm(@NotNull @Size(max = 1000) Set<@NotNull Long> ids) {
}

/** The claims a bulk open opened, in the order it numbered them, and how many it refused. */
public record BulkOpenView(List<ClaimView> opened, int refused) {
}

private final ClaimService service;
private final ClaimBulkService bulk;

public ClaimController(ClaimService service, ClaimBulkService bulk) {
    this.service = service;
    this.bulk = bulk;
}

/** All the claims on the sheet, newest first. */
@GetMapping("/claims")
public List<ClaimView> list(
        @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
    return service.list(sheetId).stream().map(ClaimView::of).toList();
}

@PostMapping("/people/{personId}/claims")
public ClaimView add(
        @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
        @PathVariable Long personId, @Valid @RequestBody ClaimForm form,
        @SessionAttribute(SessionController.USER) String user) {
    return ClaimView.of(service.add(user, sheetId, personId, form.amount(), form.date(), form.note(),
            form.corrects()));
}

@PutMapping("/claims/{id}")
public ClaimView update(
        @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
        @PathVariable Long id, @Valid @RequestBody ClaimForm form,
        @SessionAttribute(SessionController.USER) String user) {
    return ClaimView.of(service.update(user, sheetId, id, form.amount(), form.date(), form.note(),
            form.corrects()));
}

/** Opens the user's editor on the claim, holding it for them until it is saved or cancelled. */
@PostMapping("/claims/{id}/lock")
public ClaimView lock(
        @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
        @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
    return ClaimView.of(service.lock(user, sheetId, id));
}

/** Cancels the user's editor on the claim, releasing it. */
@PostMapping("/claims/{id}/unlock")
public ClaimView unlock(
        @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
        @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
    return ClaimView.of(service.unlock(user, sheetId, id));
}

@PostMapping("/claims/{id}/open")
public ClaimView open(
        @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
        @PathVariable Long id, @SessionAttribute(SessionController.USER) String user) {
    return ClaimView.of(service.changeStatus(user, sheetId, id, ClaimStatus.OPEN));
}

@PostMapping("/claims/bulk-open")
@ViewerPasses
public BulkOpenView bulkOpen(
    this.holidays = holidays;
    this.audit = audit;
}

/** All the claims on the sheet, newest first. */
@Transactional(readOnly = true)
public List<Claim> list(String sheetId) {
    return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
}

/**
 * Adds a claim for the person; a missing date takes the sheet's entry date, or its today when that is blank. Its
 * due-by is fixed as the terms-th business day after its date, skipping weekends and the sheet's holidays then, and its period is the one its due-by falls in: one whose
 * due-by falls in a soft-closed period is a late entry. Refused when its due-by falls in a closed period or when
 * it is dated after the person's retirement date, and a correction (a negative amount) unless it corrects a settled claim of
 * the person.
 */
@Transactional
public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
        String corrects) {
    LocalDate on = dateOrEntryDate(sheetId, date);
    Person person = person(sheetId, personId);
    LocalDate dueBy = holidays.dueBy(sheetId, on, termsFor(sheetId, person, on));
    refuseInClosedPeriod(sheetId, dueBy);
    RollupService.Snapshot before = rollup.snapshot(sheetId);
    refuseAfterRetirement(person, on);
    String corrected = correctedNumber(sheetId, personId, amount, corrects);
    Claim claim = new Claim(sheetId, personId, scaled(amount), on, noteOf(note));
    claim.setCorrects(corrected);
    claim.setRoundsOn(roundsOn(sheetId, corrected, on));
    claim.setDueBy(dueBy);
    claim.setLateEntry(periods.existsBySheetIdAndSoftClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
            dueBy, dueBy));
    logStatus(by, sheetId, person, claim);
    Claim added = claims.saveAndFlush(claim);
    audit.recordOnCommit(record("CLAIM_ADDED", by, person, added));
    if (added.isLateEntry()) {
        audit.recordOnCommit(record("LATE_ENTRY", by, person, added));
    }
    rollup.recordChanges(by, sheetId, before);
    return added;
}

/**
 * Edits a claim; its due-by, and so its period, stay as they were fixed. Refused unless it is a draft, and when
 * its due-by falls in a closed period. An open claim is changed by voiding it and adding a new one.
 */
@Transactional
public Claim update(String by, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
        String corrects) {
    LocalDate on = dateOrToday(sheetId, date);
    Claim claim = claims.findByIdAndSheetId(id, sheetId)
